#include <cstdint>
#include <optional>
#include <string>
#include <vector>

struct Section
{
    std::string name;
    std::uint32_t virtualAddress, virtualSize, rawPointer, rawSize, characteristics;
};

struct Headers
{
    std::uint16_t machine;
    std::uint32_t entryPoint;
    std::uint64_t imageBase;
    std::vector<Section> sections;
};

static std::uint64_t le(const std::vector<std::uint8_t>& b, std::size_t at, int n)
{
    std::uint64_t v{ 0 };
    for (int i{ 0 }; i < n; ++i) v |= static_cast<std::uint64_t>(b[at + i]) << (8 * i);
    return v;
}

std::optional<Headers> readHeaders(const std::vector<std::uint8_t>& file)
{
    if (file.size() < 0x40 || file[0] != 'M' || file[1] != 'Z') return std::nullopt;
    const std::size_t pe{ static_cast<std::size_t>(le(file, 0x3C, 4)) };
    if (pe + 24 > file.size() || le(file, pe, 4) != 0x00004550) return std::nullopt;
    const std::size_t fileHeader{ pe + 4 };
    const std::size_t count{ static_cast<std::size_t>(le(file, fileHeader + 2, 2)) };
    const std::size_t optionalSize{ static_cast<std::size_t>(le(file, fileHeader + 16, 2)) };
    const std::size_t optional{ fileHeader + 20 };
    if (optional + 32 > file.size() || le(file, optional, 2) != 0x20B) return std::nullopt;
    const std::size_t table{ optional + optionalSize };
    if (table + count * 40 > file.size()) return std::nullopt;

    Headers h{};
    h.machine = static_cast<std::uint16_t>(le(file, fileHeader, 2));
    h.entryPoint = static_cast<std::uint32_t>(le(file, optional + 16, 4));
    h.imageBase = le(file, optional + 24, 8);
    for (std::size_t i{ 0 }; i < count; ++i)
    {
        const std::size_t at{ table + i * 40 };
        Section s{};
        for (int k{ 0 }; k < 8 && file[at + k] != 0; ++k) s.name += static_cast<char>(file[at + k]);
        s.virtualSize = static_cast<std::uint32_t>(le(file, at + 8, 4));
        s.virtualAddress = static_cast<std::uint32_t>(le(file, at + 12, 4));
        s.rawSize = static_cast<std::uint32_t>(le(file, at + 16, 4));
        s.rawPointer = static_cast<std::uint32_t>(le(file, at + 20, 4));
        s.characteristics = static_cast<std::uint32_t>(le(file, at + 36, 4));
        h.sections.push_back(s);
    }
    return h;
}

std::optional<std::uint32_t> rvaToOffset(const Headers& h, std::uint32_t rva)
{
    for (const Section& s : h.sections)
    {
        if (rva < s.virtualAddress || rva - s.virtualAddress >= s.virtualSize) continue;
        if (rva - s.virtualAddress >= s.rawSize) return std::nullopt;
        return rva - s.virtualAddress + s.rawPointer;
    }
    return std::nullopt;
}

unitTests:
#include <cstring>
using Bytes = std::vector<std::uint8_t>;
struct Sec { const char* name; std::uint32_t va, vsize, raw, rawSize, ch; };
static void put(Bytes& b, std::size_t at, std::uint64_t v, int n) { for (int i{ 0 }; i < n; ++i) b[at + i] = static_cast<std::uint8_t>(v >> (8 * i)); }
static Bytes makePe(const std::vector<Sec>& secs, std::uint32_t entry, std::uint64_t base)
{
    Bytes b(0x800, 0);
    b[0] = 'M'; b[1] = 'Z'; put(b, 0x3C, 0x80, 4);
    b[0x80] = 'P'; b[0x81] = 'E';
    put(b, 0x84, 0x8664, 2); put(b, 0x86, secs.size(), 2); put(b, 0x94, 0xF0, 2); put(b, 0x96, 0x22, 2);
    put(b, 0x98, 0x20B, 2); put(b, 0x98 + 16, entry, 4); put(b, 0x98 + 24, base, 8);
    put(b, 0x98 + 32, 0x1000, 4); put(b, 0x98 + 36, 0x200, 4); put(b, 0x98 + 108, 16, 4);
    for (std::size_t i{ 0 }; i < secs.size(); ++i)
    {
        const std::size_t at{ 0x188 + i * 40 };
        std::memcpy(&b[at], secs[i].name, std::strlen(secs[i].name));
        put(b, at + 8, secs[i].vsize, 4); put(b, at + 12, secs[i].va, 4);
        put(b, at + 16, secs[i].rawSize, 4); put(b, at + 20, secs[i].raw, 4); put(b, at + 36, secs[i].ch, 4);
    }
    return b;
}
static const std::vector<Sec> SECS{
    { ".text", 0x1000, 0x1A0, 0x400, 0x200, 0x60000020 },
    { ".rdata", 0x2000, 0x90, 0x600, 0x200, 0x40000040 },
    { ".data", 0x3000, 0x1400, 0, 0, 0xC0000040 },
};

TEST("headers") {
    const auto h{ readHeaders(makePe(SECS, 0x1010, 0x140000000)) };
    CHECK(h.has_value());
    if (!h) return;
    CHECK_EQ(h->machine, 0x8664);
    CHECK_EQ(h->entryPoint, 0x1010u);
    CHECK_EQ(h->imageBase, 0x140000000ull);
    CHECK_EQ(h->sections.size(), 3u);
}
TEST("sections") {
    const auto h{ readHeaders(makePe(SECS, 0x1010, 0x140000000)) };
    if (!h || h->sections.size() != 3) { CHECK(false); return; }
    CHECK_EQ(h->sections[0].name, std::string(".text"));
    CHECK_EQ(h->sections[1].name, std::string(".rdata"));
    CHECK_EQ(h->sections[1].rawPointer, 0x600u);
    CHECK_EQ(h->sections[2].virtualSize, 0x1400u);
    CHECK_EQ(h->sections[0].characteristics, 0x60000020u);
}
TEST("rva to file offset") {
    const auto h{ readHeaders(makePe(SECS, 0x1010, 0x140000000)) };
    if (!h) { CHECK(false); return; }
    CHECK_EQ(rvaToOffset(*h, 0x1010).value_or(0), 0x410u);
    CHECK_EQ(rvaToOffset(*h, 0x2048).value_or(0), 0x648u);
    CHECK(!rvaToOffset(*h, 0x3000).has_value());
    CHECK(!rvaToOffset(*h, 0x2090).has_value());
    CHECK(!rvaToOffset(*h, 0x5000).has_value());
}
TEST("not a valid PE") {
    Bytes b{ makePe(SECS, 0x1010, 0x140000000) };
    Bytes noMz{ b }; noMz[0] = 'X';
    CHECK(!readHeaders(noMz).has_value());
    Bytes noPe{ b }; noPe[0x81] = 'X';
    CHECK(!readHeaders(noPe).has_value());
    Bytes thirtyTwo{ b }; put(thirtyTwo, 0x98, 0x10B, 2);
    CHECK(!readHeaders(thirtyTwo).has_value());
    Bytes farAway{ b }; put(farAway, 0x3C, 0x7FFF0000, 4);
    CHECK(!readHeaders(farAway).has_value());
    CHECK(!readHeaders(Bytes(10, 0)).has_value());
}

